from html import escape as esc

def form(service='general', root=False):
    fid='contact-form' if root else 'lead-form'
    mid='project-message' if root else 'lead-message'
    prefix='contact' if root else 'lead'
    name={'sites-applications':'Votre activité et la plateforme à créer','ia-automatisation':'Votre scénario d’agent IA ou d’automatisation','design-marketing':'Votre offre et les supports souhaités','externalisation-bpo':'Les tâches à déléguer et leur volume'}.get(service,'Parlez-nous de votre besoin')
    return f'''<form class="lead-form{' contact-form' if root else ''}" id="{fid}" data-lead-form method="post" action="/api/leads" data-service="{service}">
<div class="form-pair"><div><label class="field-label" for="{prefix}-name">Votre nom</label><input id="{prefix}-name" name="name" autocomplete="name" maxlength="100" minlength="2" required></div><div><label class="field-label" for="{prefix}-reply">Email ou WhatsApp</label><input id="{prefix}-reply" name="contact" type="text" autocomplete="email" maxlength="160" required placeholder="vous@entreprise.com ou +261…"></div></div>
<label class="field-label" for="{mid}">{name}</label><textarea id="{mid}" name="message" rows="4" minlength="15" maxlength="3000" required placeholder="Votre contexte et la priorité à traiter…"></textarea>
<details class="lead-extra"><summary>Ajouter quelques précisions (facultatif)</summary><label class="field-label" for="{prefix}-details">Outils, volume, échéance ou contraintes</label><textarea name="details" id="{prefix}-details" rows="3" maxlength="2500" placeholder="Ce qui nous aiderait à préparer l’échange…"></textarea></details>
<div class="form-trap" aria-hidden="true"><label>Votre site<input name="website" tabindex="-1" autocomplete="off"></label></div>
<label class="lead-consent"><input name="consent" type="checkbox" required><span>J’accepte qu’ILOCAP utilise ces informations pour traiter ma demande et me recontacter. <a class="inline-link" href="/politique-de-confidentialite" target="_blank" rel="noopener">Confidentialité</a></span></label>
<p class="lead-context" data-context-note></p><p class="form-error" data-form-error role="alert"></p><button class="button{' gold' if root else ''}" type="submit">Envoyer ma demande</button>
<div {'id="contact-ready"' if root else ''} data-form-result hidden role="status"><p data-receipt></p><div class="actions"><a class="button{' light' if root else ' secondary'}" data-whatsapp href="https://wa.me/261343807857" target="_blank" rel="noopener noreferrer">Poursuivre sur WhatsApp</a></div></div>
<p class="lead-reassurance">Après réception, nous précisons ensemble le périmètre et la suite, avant tout engagement.</p><noscript><p>Activez JavaScript pour utiliser le formulaire, ou <a href="https://wa.me/261343807857">contactez-nous sur WhatsApp</a>.</p></noscript></form>'''

EXAMPLES={
 'sites-applications':('Un premier périmètre, concret.', [('Votre point de départ','Une offre à présenter, un parcours de commande ou une tâche à centraliser.'),('Des livrables à examiner','Une arborescence, des écrans et une liste de fonctions pour la première version.'),('Votre validation','Vous validez les parcours et le périmètre avant la réalisation.')]),
 'ia-automatisation':('Un processus, un test, des critères.', [('Votre point de départ','Une tâche récurrente, ses entrées, les outils utilisés et les exceptions.'),('Des livrables à examiner','Un schéma du processus, les règles et un premier workflow à tester.'),('Votre validation','Nous comparons les résultats à un échantillon et aux contrôles convenus.')]),
 'design-marketing':('Une offre, un message, les bons supports.', [('Votre point de départ','Une offre prioritaire, une cible et l’action attendue du public.'),('Des livrables à examiner','Une direction visuelle, les textes et les formats choisis ensemble.'),('Votre validation','Vous validez les supports avant diffusion et les indicateurs à observer.')]),
 'externalisation-bpo':('Commencez par une mission pilote.', [('Votre point de départ','Des consignes, un volume de tâches et un exemple de résultat conforme.'),('Des livrables à examiner','Un échantillon traité, une liste de contrôles et le relevé des exceptions.'),('Votre validation','Vous validez la qualité et les corrections avant la montée en charge.')])}

def example(service):
    title,items=EXAMPLES[service]
    return '<section class="container landing-section pilot-section"><p class="eyebrow">EXEMPLE DE DÉMARRAGE · À ADAPTER ENSEMBLE</p><h2>'+esc(title)+'</h2><div class="pilot-grid">'+''.join('<article><span>0'+str(i+1)+'</span><h3>'+esc(t)+'</h3><p>'+esc(d)+'</p></article>' for i,(t,d) in enumerate(items))+'</div><p class="caption">Exemple de démarche. Les livrables, les critères de validation et le budget sont précisés selon votre situation.</p></section>'

def agent_focus():
    return '''<article class="agent-focus" id="agents-ia" aria-labelledby="agent-focus-title"><div class="agent-focus-copy"><p class="eyebrow">RELATION CLIENT · CENTRES D’APPELS</p><h2 id="agent-focus-title">Agents IA.<br><em>Chaque échange compte.</em></h2><p>Qualifier vos prospects, répondre aux demandes, prendre rendez-vous : des agents IA qui font avancer la relation client.</p><ul class="agent-criteria"><li><strong>Prospecter</strong><span>Qualifier les contacts et préparer la suite.</span></li><li><strong>Répondre</strong><span>Informer, traiter les objections, orienter.</span></li><li><strong>Accompagner</strong><span>Fixer un rendez-vous ou passer le relais.</span></li></ul><details class="team-context"><summary>Aller plus loin</summary><p>Voix ou messages, prise de commande, paiement et connexion à vos outils : les possibilités sont étudiées selon votre projet, avec des règles et une supervision définies ensemble.</p></details><a class="button" href="ia-automatisation.html?offre=agents-relation-client#projet">Étudier mon projet d’agent IA</a></div><figure><img src="assets/agents-ia-relation-client.webp" alt="Illustration de scénarios d’agents IA pour l’orientation des demandes, l’appui aux conseillers et le passage de relais." width="1254" height="1254" loading="lazy"><figcaption>Illustration de scénarios d’agents IA.</figcaption></figure></article>'''
